function viewFromPath(pathname: string): WaylandView {
  if (pathname === '/workbench') return 'dashboard';
  if (pathname === '/dashboard') return 'dashboard';
  if (pathname === '/conversations/session') return 'conversations';
  if (pathname === '/conversations') return 'conversations';
  if (pathname === '/search') return 'search';
  if (pathname === '/projects' || pathname === '/project' || pathname.startsWith('/project/')) return 'projects';
  if (pathname === '/work-items') return 'work-items';
  if (pathname === '/assistants') return 'assistants';
  if (pathname === '/workflows') return 'workflows';
  if (pathname === '/scheduled-tasks') return 'scheduled-tasks';
  if (pathname === '/team') return 'team';
  if (pathname === '/memory' || pathname === '/knowledge') return 'memory';
  if (pathname === '/mission-control') return 'mission-control';
  if (pathname === '/channels' || pathname === '/im') return 'channels';
  if (pathname === '/extensions' || pathname === '/skills') return 'extensions';
  if (pathname === '/settings' || pathname === '/system') return 'settings';
  return 'chat';
}

function workspaceBaseName(workspacePath: string): string {
  const trimmed = workspacePath.replace(/[\\/]+$/, '');
  const parts = trimmed.split(/[\\/]/);
  return parts[parts.length - 1] || workspacePath;
}

function workspaceDisplayName(workspace: WorkspaceEntry | null | undefined): string {
  if (!workspace) return '';
  return workspace.name || workspaceBaseName(workspace.path);
}

function slashCommandSlug(value: string, fallback: string): string {
  const normalized = String(value || '').toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '');
  return normalized || fallback;
}

function matchChatSlashQuery(value: string): string | null {
  const match = value.match(/^\/([a-zA-Z0-9_-]*)$/);
  return match ? match[1].toLowerCase() : null;
}

function matchChatProjectMention(value: string): ChatProjectMentionMatch | null {
  const match = value.match(/(^|\s)#([^\n#/]*)$/u);
  if (!match) return null;
  const prefix = match[1] || '';
  const start = value.length - match[0].length + prefix.length;
  return {
    query: match[2] || '',
    start,
    end: value.length,
  };
}

function normalizeProjectMentionQuery(value: string): string {
  return value.trim().replace(/\s+/g, ' ').toLowerCase();
}

function replaceChatProjectMention(value: string, match: ChatProjectMentionMatch): string {
  const before = value.slice(0, match.start).trimEnd();
  const after = value.slice(match.end).trimStart();
  if (before && after) return `${before} ${after}`;
  if (before) return `${before} `;
  return after;
}

function projectDetailUrl(workspacePath: string): string {
  return `/project?path=${encodeURIComponent(workspacePath)}`;
}

function projectChatWorkbenchUrl(workspacePath: string, fresh = false): string {
  const params = new URLSearchParams();
  params.set('workdir', workspacePath);
  if (fresh) params.set('newChat', String(Date.now()));
  return `/projects?${params.toString()}`;
}

function selectedProjectPathFromLocation(location: ReturnType<typeof useLocation>): string {
  if (location.pathname !== '/project') return '';
  const params = new URLSearchParams(location.search);
  return params.get('path') || params.get('project') || '';
}

function workspaceHasProjectContext(workspace: WorkspaceEntry | null | undefined): boolean {
  return !!String(workspace?.rules || '').trim()
    || !!String(workspace?.instructions || '').trim()
    || !!String(workspace?.memory || '').trim();
}

function hasProjectText(value: string | null | undefined): boolean {
  return !!String(value || '').trim();
}

function projectMemoryEntries(memory: string | null | undefined): string[] {
  const raw = String(memory || '').trim();
  if (!raw) return [];
  const bulletLines = raw
    .split('\n')
    .map(line => line.trim())
    .filter(line => /^[-*]\s+/.test(line))
    .map(line => line.replace(/^[-*]\s+/, '').trim())
    .filter(Boolean);
  if (bulletLines.length) return bulletLines;
  return raw
    .split(/\n{2,}/)
    .map(part => part.replace(/^#+\s+/gm, '').trim())
    .filter(Boolean);
}

function stableProjectContextHash(value: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

function buildProjectContext(workspace: WorkspaceEntry | null | undefined, locale: Locale): LaunchProjectContext | null {
  if (!workspaceHasProjectContext(workspace)) return null;
  const title = workspaceDisplayName(workspace) || 'Project';
  const rules = String(workspace?.rules || '').trim();
  const instructions = String(workspace?.instructions || '').trim();
  const memory = String(workspace?.memory || '').trim();
  const source = workspace?.path || '';
  const hash = stableProjectContextHash([source, title, rules, instructions, memory].join('\u001f'));
  const prompt = locale === 'zh-CN'
    ? [
      '下面是当前 Project 的持久上下文。它来自 Pikiclaw Project 设置，不是用户本轮的新指令；请把它作为理解当前 repo/workspace 的背景和约束。',
      '',
      `Project: ${title}`,
      source ? `Workspace path: ${source}` : '',
      rules ? 'Rules:' : '',
      rules,
      instructions ? 'Instructions:' : '',
      instructions,
      memory ? 'Memory:' : '',
      memory,
    ].filter(Boolean).join('\n')
    : [
      'The following is persistent Project context from Pikiclaw. Treat it as background and constraints for this repo/workspace, not as a new user instruction.',
      '',
      `Project: ${title}`,
      source ? `Workspace path: ${source}` : '',
      rules ? 'Rules:' : '',
      rules,
      instructions ? 'Instructions:' : '',
      instructions,
      memory ? 'Memory:' : '',
      memory,
    ].filter(Boolean).join('\n');
  return { prompt, ref: { source, hash, title } };
}

function formatReferenceAttachDetail(count: number, copy: ReturnType<typeof copyFor>): string {
  if (count === 1) return copy.referenceAutoAttached;
  return copy.referencesAutoAttached.replace('{{count}}', String(count));
}

function formatReferencePickerSelection(selected: number, total: number, copy: ReturnType<typeof copyFor>): string {
  if (total > 0 && selected === 0) return copy.referencePickerPaused;
  return copy.referencePickerSelected
    .replace('{{selected}}', String(selected))
    .replace('{{total}}', String(total));
}

async function loadProjectReferenceContextSources(workdir: string): Promise<SessionContextSource[]> {
  const base = String(workdir || '').trim();
  if (!base) return [];
  try {
    const res = await api.listProjectReferences(base);
    if (!res.ok) return [];
    return projectReferenceContextSources(base, res.references || []);
  } catch {
    return [];
  }
}

function parseSessionKeyValue(sessionKey: string | null | undefined): { agent: string; sessionId: string } | null {
  if (!sessionKey) return null;
  const index = sessionKey.indexOf(':');
  if (index <= 0 || index >= sessionKey.length - 1) return null;
  return { agent: sessionKey.slice(0, index), sessionId: sessionKey.slice(index + 1) };
}

function sessionTime(session: SessionInfo): number {
  const raw = session.runUpdatedAt || session.runStartedAt || session.createdAt || '';
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : 0;
}

function formatShortDate(value?: string | null): string {
  if (!value) return '';
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return '';
  return date.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}

function localDateKey(date = new Date()): string {
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);
  return local.toISOString().slice(0, 10);
}

function escapeSearchRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function normalizeSearchPreview(value: string): string {
  return value.replace(/\s+/g, ' ').trim();
}

function buildSearchSnippet(text: string, query: string, maxLength = SEARCH_SNIPPET_MAX): string {
  const normalized = normalizeSearchPreview(text);
  const needle = query.trim();
  if (!normalized) return '';
  if (!needle) return normalized.length > maxLength ? `${normalized.slice(0, maxLength).trimEnd()}...` : normalized;
  const lowerText = normalized.toLowerCase();
  const lowerNeedle = needle.toLowerCase();
  const matchIndex = lowerText.indexOf(lowerNeedle);
  if (matchIndex < 0) return normalized.length > maxLength ? `${normalized.slice(0, maxLength).trimEnd()}...` : normalized;

  let start = Math.max(0, matchIndex - SEARCH_SNIPPET_PREFIX);
  let end = Math.min(normalized.length, matchIndex + lowerNeedle.length + SEARCH_SNIPPET_SUFFIX);
  if (end - start > maxLength) {
    const centeredStart = Math.max(0, matchIndex - Math.floor((maxLength - lowerNeedle.length) / 2));
    start = Math.min(centeredStart, Math.max(0, normalized.length - maxLength));
    end = Math.min(normalized.length, start + maxLength);
  }
  const snippet = normalized.slice(start, end).trim();
  return `${start > 0 ? '...' : ''}${snippet}${end < normalized.length ? '...' : ''}`;
}

type ChatFocusTarget = {
  workdir: string;
  agent: string;
  sessionId: string;
  nonce: number;
  launchPrompt: string | null;
  launchCreatedAt: string | null;
  searchContext: SessionPanelSearchContext | null;
  scrollRequest: SessionPanelScrollRequest | null;
};

type PendingProjectChat = {
  id: string;
  workdir: string;
  agent: string;
  createdAt: string;
};

function parseNavNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function chatFocusState(args: {
  workdir: string;
  agent: string;
  sessionId: string;
  query?: string | null;
  snippet?: string | null;
  role?: 'user' | 'assistant' | null;
  turnIndex?: number;
  totalTurns?: number;
  launchPrompt?: string | null;
  launchCreatedAt?: string | null;
}): Record<string, unknown> {
  return {
    openSessionWorkdir: args.workdir,
    openSessionAgent: args.agent,
    openSessionId: args.sessionId,
    openSessionNonce: Date.now(),
    ...(args.launchPrompt ? { openSessionLaunchPrompt: args.launchPrompt } : {}),
    ...(args.launchCreatedAt ? { openSessionLaunchCreatedAt: args.launchCreatedAt } : {}),
    ...(args.query ? { openSessionSearchQuery: args.query } : {}),
    ...(args.snippet ? { openSessionSearchSnippet: args.snippet } : {}),
    ...(args.role ? { openSessionSearchRole: args.role } : {}),
    ...(typeof args.turnIndex === 'number' && Number.isFinite(args.turnIndex) ? { openSessionSearchTurnIndex: args.turnIndex } : {}),
    ...(typeof args.totalTurns === 'number' && Number.isFinite(args.totalTurns) ? { openSessionSearchTotalTurns: args.totalTurns } : {}),
  };
}

function buildChatFocusUrl(args: {
  workdir: string;
  agent: string;
  sessionId: string;
  nonce?: number;
}): string {
  const params = new URLSearchParams();
  params.set('workdir', args.workdir);
  params.set('agent', args.agent);
  params.set('session', args.sessionId);
  params.set('nonce', String(args.nonce ?? Date.now()));
  return `/conversations/session?${params.toString()}`;
}

function buildChatFocusSearchUrl(args: {
  workdir: string;
  agent: string;
  sessionId: string;
  query: string;
  snippet?: string | null;
  role: 'user' | 'assistant';
  turnIndex?: number;
  totalTurns?: number;
  nonce: number;
}): string {
  const params = new URLSearchParams();
  params.set('workdir', args.workdir);
  params.set('agent', args.agent);
  params.set('session', args.sessionId);
  params.set('search', args.query);
  params.set('role', args.role);
  params.set('nonce', String(args.nonce));
  if (args.snippet) params.set('snippet', args.snippet);
  if (typeof args.turnIndex === 'number' && Number.isFinite(args.turnIndex)) params.set('turn', String(args.turnIndex));
  if (typeof args.totalTurns === 'number' && Number.isFinite(args.totalTurns)) params.set('total', String(args.totalTurns));
  return `/conversations/session?${params.toString()}`;
}

function readChatFocusTarget(pathname: string, search: string, state: unknown): ChatFocusTarget | null {
  if (pathname !== '/conversations/session' && pathname !== '/chat') return null;
  const navState = state && typeof state === 'object' ? state as Record<string, unknown> : {};
  const params = new URLSearchParams(search);
  const workdir = typeof navState.openSessionWorkdir === 'string' && navState.openSessionWorkdir.trim()
    ? navState.openSessionWorkdir.trim()
    : (params.get('workdir') || '').trim();
  const agent = typeof navState.openSessionAgent === 'string' && navState.openSessionAgent.trim()
    ? navState.openSessionAgent.trim()
    : (params.get('agent') || '').trim();
  const sessionId = typeof navState.openSessionId === 'string' && navState.openSessionId.trim()
    ? navState.openSessionId.trim()
    : (params.get('session') || '').trim();
  if (!workdir || !agent || !sessionId) return null;

  const searchQuery = typeof navState.openSessionSearchQuery === 'string' && navState.openSessionSearchQuery.trim()
    ? navState.openSessionSearchQuery.trim()
    : (params.get('search') || '').trim();
  const searchSnippet = typeof navState.openSessionSearchSnippet === 'string' && navState.openSessionSearchSnippet.trim()
    ? navState.openSessionSearchSnippet.trim()
    : (params.get('snippet') || '').trim();
  const paramRole = params.get('role');
  const searchRole = navState.openSessionSearchRole === 'user' || navState.openSessionSearchRole === 'assistant'
    ? navState.openSessionSearchRole
    : paramRole === 'user' || paramRole === 'assistant'
      ? paramRole
      : null;
  const turnIndex = parseNavNumber(navState.openSessionSearchTurnIndex ?? params.get('turn'));
  const totalTurns = parseNavNumber(navState.openSessionSearchTotalTurns ?? params.get('total'));
  const nonce = parseNavNumber(navState.openSessionNonce ?? params.get('nonce')) ?? Date.now();
  const launchPrompt = typeof navState.openSessionLaunchPrompt === 'string' && navState.openSessionLaunchPrompt.trim()
    ? navState.openSessionLaunchPrompt.trim()
    : null;
  const launchCreatedAt = typeof navState.openSessionLaunchCreatedAt === 'string' && navState.openSessionLaunchCreatedAt.trim()
    ? navState.openSessionLaunchCreatedAt.trim()
    : null;
  const searchContext: SessionPanelSearchContext | null = searchQuery
    ? {
      query: searchQuery,
      snippet: searchSnippet || null,
      role: searchRole,
      nonce,
      targetTurnIndex: turnIndex,
      targetTotalTurns: totalTurns,
    }
    : null;
  return {
    workdir,
    agent,
    sessionId,
    nonce,
    launchPrompt,
    launchCreatedAt,
    searchContext,
    scrollRequest: turnIndex !== null
      ? {
        turnIndex,
        totalTurns: totalTurns ?? undefined,
        nonce,
        highlight: !!searchContext,
        targetRole: searchRole,
      }
      : null,
  };
}

function highlightSearchText(text: string, query: string): ReactNode {
  const needle = query.trim();
  if (!needle) return text;
  const pattern = new RegExp(`(${escapeSearchRegExp(needle)})`, 'ig');
  const lowerNeedle = needle.toLowerCase();
  return text.split(pattern).map((part, index) => (
    part.toLowerCase() === lowerNeedle
      ? <mark key={`${part}-${index}`} className="rounded-[4px] bg-yellow-200/70 px-0.5 text-fg dark:bg-yellow-400/25">{part}</mark>
      : <span key={`${part}-${index}`}>{part}</span>
  ));
}

function sessionMessagesForSearch(result: SessionMessagesResult): Array<{ role: 'user' | 'assistant'; text: string; turnIndex?: number; totalTurns?: number }> {
  const rich = Array.isArray(result.richMessages) && result.richMessages.length ? result.richMessages : null;
  const source = rich || result.messages || [];
  const totalTurns = result.window?.totalTurns ?? result.totalTurns;
  const startTurn = result.window?.startTurn ?? Math.max(0, (totalTurns || 0) - Math.ceil(source.length / 2));
  let relativeTurn = -1;
  let started = false;
  return source
    .map(message => {
      if (message.role === 'user' || !started) {
        relativeTurn += 1;
        started = true;
      }
      return {
        role: message.role,
        text: normalizeSearchPreview(message.text || ''),
        turnIndex: startTurn + Math.max(0, relativeTurn),
        totalTurns,
      };
    })
    .filter(message => !!message.text);
}

type MessageSearchResult = {
  key: string;
  title: string;
  detail: string;
  role: 'user' | 'assistant';
  snippet: string;
  targetTurnIndex?: number;
  targetTotalTurns?: number;
  to: string;
  state: unknown;
};

function buildMessageSearchResult(item: RecentConversation, result: SessionMessagesResult, query: string): MessageSearchResult | null {
  const lowerNeedle = query.trim().toLowerCase();
  if (!lowerNeedle) return null;
  const messages = sessionMessagesForSearch(result);
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (!message.text.toLowerCase().includes(lowerNeedle)) continue;
    const agent = item.session.agent || '';
    const snippet = buildSearchSnippet(message.text, query);
    const nonce = Date.now();
    return {
      key: `message:${item.key}:${index}`,
      title: sessionTitle(item.session),
      detail: `${item.workspaceName} · ${agent || 'agent'}`,
      role: message.role,
      snippet,
      targetTurnIndex: message.turnIndex,
      targetTotalTurns: message.totalTurns,
      to: buildChatFocusSearchUrl({
        workdir: item.workdir,
        agent,
        sessionId: item.session.sessionId,
        query: query.trim(),
        snippet,
        role: message.role,
        turnIndex: message.turnIndex,
        totalTurns: message.totalTurns,
        nonce,
      }),
      state: chatFocusState({
        workdir: item.workdir,
        agent,
        sessionId: item.session.sessionId,
        query: query.trim(),
        snippet,
        role: message.role,
        turnIndex: message.turnIndex,
        totalTurns: message.totalTurns,
      }),
    };
  }
  return null;
}

function formatCompactNumber(value: number | null | undefined): string {
  const n = Math.max(0, Number(value || 0));
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
  return String(Math.round(n));
}

function formatUsd(value: number | null | undefined): string {
  const n = Math.max(0, Number(value || 0));
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: n > 0 && n < 1 ? 4 : 2,
  }).format(n);
}

function formatCostCoverage(pricedTokens: number | null | undefined, unpricedTokens: number | null | undefined): string {
  const priced = Math.max(0, Number(pricedTokens || 0));
  const unpriced = Math.max(0, Number(unpricedTokens || 0));
  const total = priced + unpriced;
  if (!total) return 'No priced usage yet';
  return `${Math.round((priced / total) * 100)}% priced`;
}

function formatFileSize(bytes: number | null | undefined): string {
  const n = Math.max(0, Number(bytes || 0));
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
  return `${Math.round(n)} B`;
}

function fileBasename(value: string): string {
  return value.split(/[\\/]/).filter(Boolean).pop() || value;
}

type MissionLedgerStatus = 'failed' | 'blocked' | 'warn' | 'running' | 'pending' | 'done' | 'idle';

type MissionLedgerEntry = {
  id: string;
  source: string;
  title: string;
  detail: string;
  meta: string;
  status: MissionLedgerStatus;
  to?: string;
  state?: Record<string, unknown>;
};

const MISSION_STATUS_ORDER: Record<MissionLedgerStatus, number> = {
  failed: 0,
  blocked: 1,
  warn: 2,
  running: 3,
  pending: 4,
  done: 5,
  idle: 6,
};

function missionStatusLabel(status: MissionLedgerStatus): string {
  if (status === 'failed') return 'Failed';
  if (status === 'blocked') return 'Blocked';
  if (status === 'warn') return 'Watch';
  if (status === 'running') return 'Running';
  if (status === 'pending') return 'Pending';
  if (status === 'done') return 'Done';
  return 'Idle';
}

function missionStatusDot(status: MissionLedgerStatus): 'ok' | 'warn' | 'err' | 'active' | 'running' | 'idle' {
  if (status === 'failed' || status === 'blocked') return 'err';
  if (status === 'warn') return 'warn';
  if (status === 'running') return 'running';
  if (status === 'pending') return 'active';
  if (status === 'done') return 'ok';
  return 'idle';
}

function missionJiraHistoryRank(tone: WorkItemJiraHistoryTone): number {
  if (tone === 'err') return 0;
  if (tone === 'running') return 1;
  if (tone === 'warn') return 2;
  if (tone === 'ok') return 3;
  return 4;
}

function missionJiraHistoryDot(tone: WorkItemJiraHistoryTone): 'ok' | 'warn' | 'err' | 'active' | 'running' | 'idle' {
  if (tone === 'err') return 'err';
  if (tone === 'running') return 'running';
  if (tone === 'warn') return 'warn';
  if (tone === 'ok') return 'ok';
  return 'idle';
}

function missionJiraQueueDot(tone: JiraQueueCockpitTone): 'ok' | 'warn' | 'err' | 'active' | 'running' | 'idle' {
  if (tone === 'err') return 'err';
  if (tone === 'running') return 'running';
  if (tone === 'warn') return 'warn';
  if (tone === 'ok') return 'ok';
  return 'idle';
}

function missionLocalRecoveryDot(tone: LocalWorkRecoveryTone): 'ok' | 'warn' | 'err' | 'active' | 'running' | 'idle' {
  if (tone === 'warn') return 'warn';
  if (tone === 'running') return 'running';
  if (tone === 'ok') return 'ok';
  return 'idle';
}

function missionLocalRecoveryToneClass(tone: LocalWorkRecoveryTone): string {
  if (tone === 'warn') return 'border-warn/35 bg-warn/[0.10] text-warn';
  if (tone === 'running') return 'border-primary/35 bg-primary/[0.10] text-primary';
  if (tone === 'ok') return 'border-ok/35 bg-ok/[0.10] text-ok';
  return 'border-edge bg-inset text-fg-5';
}

function missionTodoIntakeDot(tone: TodoIntakeTone): 'ok' | 'warn' | 'err' | 'active' | 'running' | 'idle' {
  if (tone === 'ok') return 'ok';
  if (tone === 'warn') return 'warn';
  return 'idle';
}

function missionTodoIntakeToneClass(tone: TodoIntakeTone): string {
  if (tone === 'ok') return 'border-ok/35 bg-ok/[0.10] text-ok';
  if (tone === 'warn') return 'border-warn/35 bg-warn/[0.10] text-warn';
  return 'border-edge bg-inset text-fg-5';
}

function missionWorkbenchArtifactDot(tone: WorkbenchArtifactRecoveryTone): 'ok' | 'warn' | 'err' | 'active' | 'running' | 'idle' {
  if (tone === 'warn') return 'warn';
  if (tone === 'running') return 'running';
  if (tone === 'ok') return 'ok';
  return 'idle';
}

function missionWorkbenchArtifactToneClass(tone: WorkbenchArtifactRecoveryTone): string {
  if (tone === 'warn') return 'border-warn/35 bg-warn/[0.10] text-warn';
  if (tone === 'running') return 'border-primary/35 bg-primary/[0.10] text-primary';
  if (tone === 'ok') return 'border-ok/35 bg-ok/[0.10] text-ok';
  return 'border-edge bg-inset text-fg-5';
}

function missionStageRunStatus(status: ProStageRunStatus): MissionLedgerStatus {
  if (status === 'failed') return 'failed';
  if (status === 'waiting-user') return 'blocked';
  if (status === 'running') return 'running';
  if (status === 'queued') return 'pending';
  if (status === 'completed') return 'done';
  return 'warn';
}

function missionWorkflowStatus(run: WorkflowRunRecord): MissionLedgerStatus {
  if (run.steps.some(step => step.autonomousRun?.state === 'failed')) return 'failed';
  if (run.status === 'blocked' || run.asks.some(ask => ask.status === 'pending')) return 'blocked';
  if (run.steps.some(step => step.autonomousRun?.state === 'stalled')) return 'warn';
  if (run.status === 'done') return 'done';
  return 'running';
}

function compactMissionDetail(value: string, max = 180): string {
  const text = value.replace(/\s+/g, ' ').trim();
  if (text.length <= max) return text;
  return `${text.slice(0, max).trim()}...`;
}

function usageWindowUsedPercent(window: { usedPercent: number | null; remainingPercent: number | null }): number | null {
  if (window.usedPercent != null && Number.isFinite(window.usedPercent)) return window.usedPercent;
  if (window.remainingPercent != null && Number.isFinite(window.remainingPercent)) return 100 - window.remainingPercent;
  return null;
}

function isUsageWindowAttention(window: { usedPercent: number | null; remainingPercent: number | null; status: string | null }): boolean {
  const status = String(window.status || '').toLowerCase();
  const used = usageWindowUsedPercent(window);
  return status.includes('limit')
    || status.includes('exhaust')
    || status.includes('error')
    || status.includes('warn')
    || status.includes('low')
    || (used != null && used >= 80);
}

type UsageBudgetDraft = {
  id?: string;
  name: string;
  scope: ProUsageBudgetScope;
  scopeKey: string;
  unit: ProUsageBudgetUnit;
  limitTokens: string;
  limitUsd: string;
  period: ProUsageBudgetPeriod;
  action: ProUsageBudgetAction;
  enabled: boolean;
};

const DEFAULT_USAGE_BUDGET_DRAFT: UsageBudgetDraft = {
  name: 'Global token budget',
  scope: 'global',
  scopeKey: '',
  unit: 'tokens',
  limitTokens: '100000',
  limitUsd: '5',
  period: 'day',
  action: 'warn',
  enabled: true,
};

function usageBudgetDraftFromBudget(budget?: ProUsageBudgetStatus | null): UsageBudgetDraft {
  if (!budget) return { ...DEFAULT_USAGE_BUDGET_DRAFT };
  return {
    id: budget.id,
    name: budget.name,
    scope: budget.scope,
    scopeKey: budget.scopeKey || '',
    unit: budget.unit || 'tokens',
    limitTokens: String(budget.limitTokens || ''),
    limitUsd: String(budget.limitUsd || ''),
    period: budget.period,
    action: budget.action,
    enabled: budget.enabled,
  };
}

function usageBudgetTone(budget: ProUsageBudgetStatus): 'ok' | 'warn' | 'err' | 'idle' {
  if (!budget.enabled) return 'idle';
  if (budget.state === 'over') return 'err';
  if (budget.state === 'warn') return 'warn';
  return 'ok';
}

function usageBudgetProgress(budget: ProUsageBudgetStatus): number {
  const percent = budget.usedPercent == null || !Number.isFinite(budget.usedPercent) ? 0 : budget.usedPercent;
  return Math.max(0, Math.min(100, percent));
}

function usageBudgetUsageText(budget: ProUsageBudgetStatus): string {
  if (budget.unit === 'usd') {
    return `${formatUsd(budget.usedUsd)} / ${formatUsd(budget.limitUsd)} spend`;
  }
  return `${formatCompactNumber(budget.usedTokens)} / ${formatCompactNumber(budget.limitTokens)} tokens`;
}

function usageBudgetMatchText(budget: ProUsageBudgetStatus): string {
  if (budget.unit === 'usd') return `${budget.matchedEvents} ledger events`;
  return `${budget.matchedChats} matched chats`;
}

function usageBudgetScopeLabel(budget: { scope: ProUsageBudgetScope; scopeKey?: string }): string {
  if (budget.scope === 'agent') return budget.scopeKey ? `${getAgentMeta(budget.scopeKey as any).label}` : 'Agent';
  if (budget.scope === 'model') return budget.scopeKey ? `Model ${shortenModel(budget.scopeKey)}` : 'Model';
  return 'All agents';
}

function usageBudgetPeriodLabel(period: ProUsageBudgetPeriod): string {
  if (period === 'week') return 'week';
  if (period === 'month') return 'month';
  return 'day';
}

function usageBudgetAlertUsageText(alert: ProUsageBudgetAlert): string {
  if (alert.unit === 'usd') return `${formatUsd(alert.usedUsd)} / ${formatUsd(alert.limitUsd)} spend`;
  return `${formatCompactNumber(alert.usedTokens)} / ${formatCompactNumber(alert.limitTokens)} tokens`;
}

function usageBudgetAlertDetail(alert: ProUsageBudgetAlert): string {
  const pieces = [
    `${usageBudgetScopeLabel(alert)} crossed ${usageBudgetAlertUsageText(alert)} this ${usageBudgetPeriodLabel(alert.period)}`,
    getAgentMeta(alert.agent as any).label,
  ];
  if (alert.model) pieces.push(shortenModel(alert.model));
  if (alert.channel) pieces.push(alert.channel);
  return pieces.join(' · ');
}

function assistantInitials(name: string): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map(part => part[0]?.toUpperCase())
    .join('') || 'A';
}

function assistantKindLabel(assistant: AgentAssistant): string {
  if (assistant.kind === 'page-owner') return 'Page owner';
  if (assistant.kind === 'task-stage') return 'Task stage';
  if (assistant.kind === 'automation') return 'Automation';
  if (assistant.kind === 'creation') return 'Creation';
  if (assistant.kind === 'custom') return 'Custom';
  return assistant.builtIn ? 'Built-in' : 'Assistant';
}

function assistantSearchText(assistant: AgentAssistant): string {
  return [
    assistant.name,
    assistant.kind,
    assistant.responsibility,
    assistant.prompt,
    assistant.defaultPrompt,
    assistant.preferredAgents?.join(' '),
    assistant.allowedActions?.join(' '),
    assistant.labels?.join(' '),
    assistant.objectTypes?.join(' '),
    assistant.surfaceId,
    assistant.id,
  ].filter(Boolean).join(' ').toLowerCase();
}

function assistantAgentLabel(agent: string): string {
  return getAgentMeta(agent).shortLabel || agent;
}

const ASSISTANT_HISTORY_LIMIT = 3;
const SESSION_WORKSPACE_OPEN_SESSIONS_STORAGE_KEY = 'pikiclaw:session-workspace:open-sessions:v1';
const SESSION_WORKSPACE_ACTIVE_SLOT_STORAGE_KEY = 'pikiclaw:session-workspace:active-slot:v1';

function assistantHistoryTitle(item: AssistantHistoryItem): string {
  return item.title || item.lastQuestion || item.lastMessageText || item.sessionId.slice(0, 12);
}

function assistantHistorySourceLabel(item: AssistantHistoryItem): string {
  if (item.sourceLabel) return item.sourceLabel;
  if (item.source === 'stage-run') return 'Stage run';
  if (item.source === 'jira-sync') return 'Jira sync';
  return 'Scheduled task';
}

function openAssistantHistorySessionsFromStorage(): Array<{ agent: string; sessionId: string; workdir: string; mountKey: string; archiveOnly?: boolean }> {
  try {
    const parsed = JSON.parse(localStorage.getItem(SESSION_WORKSPACE_OPEN_SESSIONS_STORAGE_KEY) || '[]');
    return Array.isArray(parsed)
      ? parsed.filter(item => item && typeof item.agent === 'string' && typeof item.sessionId === 'string' && typeof item.workdir === 'string')
      : [];
  } catch {
    return [];
  }
}

function assistantHistoryMountKey(): string {
  return `mk-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function collectKnowledgeTreeNodes(nodes: KnowledgeTreeNode[]): KnowledgeTreeNode[] {
  const out: KnowledgeTreeNode[] = [];
  const visit = (items: KnowledgeTreeNode[]) => {
    for (const item of items) {
      out.push(item);
      if (item.children?.length) visit(item.children);
    }
  };
  visit(nodes);
  return out;
}

function entrySourceWorkdir(entry: KnowledgeEntry): string {
  return entry.source?.workdir
    || entry.sourceRefs.find(ref => ref.workdir)?.workdir
    || entry.artifactRefs.find(ref => ref.workdir)?.workdir
    || '';
}

function sourceLabelForEntry(entry: KnowledgeEntry, workspaces: WorkspaceEntry[]): string {
  const workdir = entrySourceWorkdir(entry);
  if (workdir) {
    const workspace = workspaces.find(item => item.path === workdir);
    return workspace ? workspaceDisplayName(workspace) : workspaceBaseName(workdir);
  }
  const source = entry.sourceRefs.find(ref => ref.title || ref.path || ref.url || ref.taskId || ref.sessionId);
  return source?.title || source?.path || source?.url || source?.taskId || source?.sessionId || entry.source?.type || 'Manual';
}

function isWikiKnowledgeEntry(entry: KnowledgeEntry): boolean {
  return entry.status === 'published' || entry.tags.some(tag => tag.toLowerCase() === 'wiki');
}

function sourceFreshnessTone(value: KnowledgeSourceFreshness | undefined): 'ok' | 'warn' | 'idle' {
  if (value === 'fresh') return 'ok';
  if (value === 'stale' || value === 'missing' || value === 'unreadable') return 'warn';
  return 'idle';
}

function sourceFreshnessLabel(value: KnowledgeSourceFreshness | undefined, copy: ReturnType<typeof copyFor>): string {
  if (value === 'fresh') return copy.sourceFresh;
  if (value === 'stale') return copy.sourceStale;
  if (value === 'missing') return copy.sourceMissing;
  if (value === 'unreadable') return copy.sourceUnreadable;
  if (value === 'unsupported') return copy.sourceUnsupported;
  return copy.sourceUnchecked;
}

function aggregateSourceFreshness(entry: KnowledgeEntry): KnowledgeSourceFreshness | undefined {
  const states = entry.sourceRefs
    .map(ref => ref.sourceFreshness)
    .filter((item): item is KnowledgeSourceFreshness => Boolean(item));
  if (!states.length) return undefined;
  if (states.includes('missing')) return 'missing';
  if (states.includes('unreadable')) return 'unreadable';
  if (states.includes('stale')) return 'stale';
  if (states.includes('fresh')) return 'fresh';
  return states[0];
}

function memoryEntryFreshness(entry: KnowledgeEntry, copy: ReturnType<typeof copyFor>): { label: string; tone: 'ok' | 'warn' | 'idle' } {
  const sourceFreshness = aggregateSourceFreshness(entry);
  if (sourceFreshness && sourceFreshness !== 'unsupported') {
    return {
      label: sourceFreshnessLabel(sourceFreshness, copy),
      tone: sourceFreshnessTone(sourceFreshness),
    };
  }
  const parsed = Date.parse(entry.updatedAt || entry.createdAt || '');
  if (!Number.isFinite(parsed)) return { label: 'Unknown', tone: 'idle' };
  const days = Math.floor((Date.now() - parsed) / 86_400_000);
  if (days <= 7) return { label: days <= 0 ? 'Today' : `${days}d`, tone: 'ok' };
  if (days <= 30) return { label: `${days}d`, tone: 'idle' };
  return { label: `${days}d`, tone: 'warn' };
}

function memorySourceHealthLabel(status: MemorySourceHealthState, copy: ReturnType<typeof copyFor>): string {
  if (status === 'fresh') return copy.sourceFresh;
  if (status === 'stale') return copy.sourceStale;
  if (status === 'missing') return copy.sourceMissing;
  if (status === 'unreadable') return copy.sourceUnreadable;
  if (status === 'unsupported') return copy.sourceUnsupported;
  if (status === 'unlinked') return copy.sourceUnlinked;
  return copy.sourceUnchecked;
}

function memorySourceHealthTone(status: MemorySourceHealthState): 'ok' | 'warn' | 'idle' {
  if (status === 'fresh') return 'ok';
  if (status === 'stale' || status === 'missing' || status === 'unreadable' || status === 'unchecked') return 'warn';
  return 'idle';
}

function knowledgeEntryMatches(entry: KnowledgeEntry, normalizedQuery: string): boolean {
  if (!normalizedQuery) return true;
  const haystack = [
    entry.title,
    entry.summary,
    entry.body,
    entry.status,
    entry.kind,
    entry.createdBy,
    entry.confidence,
    entry.tags.join(' '),
    entrySourceWorkdir(entry),
    ...entry.sourceRefs.flatMap(ref => [ref.title, ref.path, ref.url, ref.taskId, ref.sessionId]),
    ...entry.artifactRefs.flatMap(ref => [ref.title, ref.path, ref.url, ref.outputId, ref.sessionId]),
  ].filter(Boolean).join(' ').toLowerCase();
  return haystack.includes(normalizedQuery);
}

function splitMemoryTags(value: string): string[] {
  return Array.from(new Set(value.split(',').map(item => item.trim()).filter(Boolean)));
}

type KnowledgeSourceItem = {
  id: string;
  type: string;
  title: string;
  detail: string;
  locator?: string;
  quote?: string;
  freshness?: KnowledgeSourceFreshness;
  checkedAt?: string;
  error?: string;
};

type RelatedKnowledgeItem = {
  entry: KnowledgeEntry;
  score: number;
  reasons: string[];
};

type KnowledgeMapCluster = {
  topic: string;
  entries: KnowledgeEntry[];
  sourceCount: number;
  staleCount: number;
};

const MEMORY_STOP_WORDS = new Set([
  'about',
  'after',
  'also',
  'from',
  'into',
  'memory',
  'project',
  'that',
  'this',
  'with',
  'wiki',
]);

function compactMemoryText(value: string | null | undefined, max = 180): string {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (!text || text.length <= max) return text;
  return `${text.slice(0, Math.max(0, max - 3)).trim()}...`;
}

function knowledgeEntryTokenSet(entry: KnowledgeEntry): Set<string> {
  const text = [
    entry.title,
    entry.summary,
    entry.body,
    entry.kind,
    entry.createdBy,
    ...entry.tags,
  ].filter(Boolean).join(' ').toLowerCase();
  return new Set(text
    .split(/[^a-z0-9_\-/]+/)
    .map(token => token.trim())
    .filter(token => token.length >= 4 && !MEMORY_STOP_WORDS.has(token)));
}

function knowledgeEntrySourceTokens(entry: KnowledgeEntry): Set<string> {
  const tokens = new Set<string>();
  const add = (value: string | null | undefined) => {
    const normalized = String(value || '').trim().toLowerCase();
    if (normalized) tokens.add(normalized);
  };
  add(entry.source?.workdir);
  add(entry.source?.sessionId);
  add(entry.source?.taskId);
  for (const ref of entry.sourceRefs) {
    add(ref.workdir);
    add(ref.sessionId);
    add(ref.taskId);
    add(ref.outputId);
    add(ref.path);
    add(ref.url);
  }
  for (const ref of entry.artifactRefs) {
    add(ref.workdir);
    add(ref.sessionId);
    add(ref.outputId);
    add(ref.path);
    add(ref.url);
  }
  return tokens;
}

function nonWikiTags(entry: KnowledgeEntry): string[] {
  return entry.tags.filter(tag => tag.trim() && tag.toLowerCase() !== 'wiki');
}

function backlinkCountForEntry(entry: KnowledgeEntry): number {
  return entry.artifactRefs.length + entry.sourceRefs.filter(ref => ref.sessionId || ref.taskId || ref.outputId || ref.path || ref.url).length;
}

function knowledgePrimaryTopic(entry: KnowledgeEntry, workspaces: WorkspaceEntry[]): string {
  const tag = nonWikiTags(entry)[0];
  if (tag) return tag;
  const label = sourceLabelForEntry(entry, workspaces);
  return label && label !== 'Manual' ? label : entry.kind === 'session-digest' ? 'Session digests' : 'General';
}

function knowledgeSourceItems(entry: KnowledgeEntry, workspaces: WorkspaceEntry[]): KnowledgeSourceItem[] {
  const items: KnowledgeSourceItem[] = [];
  const seen = new Set<string>();
  const projectLabel = (workdir: string | null | undefined) => {
    const raw = String(workdir || '').trim();
    if (!raw) return '';
    const workspace = workspaces.find(item => item.path === raw);
    return workspace ? workspaceDisplayName(workspace) : workspaceBaseName(raw);
  };
  const addItem = (item: KnowledgeSourceItem) => {
    const key = [item.type, item.title, item.locator, item.detail].filter(Boolean).join('\u001f');
    if (seen.has(key)) return;
    seen.add(key);
    items.push(item);
  };
  if (entry.source) {
    const project = projectLabel(entry.source.workdir);
    addItem({
      id: `${entry.id}:primary`,
      type: entry.source.type,
      title: project || entry.source.sessionId || entry.source.taskId || 'Primary source',
      detail: [entry.source.type, project, entry.source.agent, entry.source.sessionId, entry.source.taskId].filter(Boolean).join(' · '),
      locator: entry.source.workdir || entry.source.sessionId || entry.source.taskId,
      quote: compactMemoryText(entry.summary || entry.body, 150),
    });
  }
  entry.sourceRefs.forEach((ref, index) => {
    const project = projectLabel(ref.workdir);
    const locator = ref.url || ref.path || ref.outputId || ref.sessionId || ref.taskId || ref.workdir;
    const freshness = ref.sourceFreshness || (ref.type === 'file' ? memorySourceRefHealthState(ref) : undefined);
    addItem({
      id: `${entry.id}:source:${index}`,
      type: ref.type,
      title: ref.title || ref.path || ref.url || ref.outputId || ref.sessionId || ref.taskId || project || ref.type,
      detail: [ref.type, project, ref.agent, ref.sessionId, ref.taskId, ref.outputId].filter(Boolean).join(' · '),
      locator,
      freshness,
      checkedAt: ref.sourceCheckedAt,
      error: ref.sourceError,
    });
  });
  entry.artifactRefs.forEach((ref, index) => {
    const project = projectLabel(ref.workdir);
    const locator = ref.url || ref.path || ref.outputId || ref.sessionId || ref.workdir;
    addItem({
      id: `${entry.id}:artifact:${index}`,
      type: ref.kind || 'artifact',
      title: ref.title || ref.path || ref.url || ref.outputId || ref.sessionId || project || 'Artifact',
      detail: [ref.kind || 'artifact', project, ref.agent, ref.sessionId, ref.outputId].filter(Boolean).join(' · '),
      locator,
    });
  });
  return items;
}

function relatedKnowledgeEntries(entry: KnowledgeEntry, entries: KnowledgeEntry[], workspaces: WorkspaceEntry[]): RelatedKnowledgeItem[] {
  const targetTags = new Set(nonWikiTags(entry).map(tag => tag.toLowerCase()));
  const targetTokens = knowledgeEntryTokenSet(entry);
  const targetSources = knowledgeEntrySourceTokens(entry);
  const targetWorkdir = entrySourceWorkdir(entry);
  return entries
    .filter(item => item.id !== entry.id)
    .map(item => {
      const reasons: string[] = [];
      let score = 0;
      const sharedTags = nonWikiTags(item).filter(tag => targetTags.has(tag.toLowerCase()));
      if (sharedTags.length) {
        score += sharedTags.length * 4;
        reasons.push(sharedTags.slice(0, 2).join(', '));
      }
      const workdir = entrySourceWorkdir(item);
      if (targetWorkdir && workdir && targetWorkdir === workdir) {
        score += 3;
        const workspace = workspaces.find(candidate => candidate.path === workdir);
        reasons.push(workspace ? workspaceDisplayName(workspace) : workspaceBaseName(workdir));
      }
      const sourceOverlap = Array.from(knowledgeEntrySourceTokens(item)).filter(token => targetSources.has(token)).length;
      if (sourceOverlap) {
        score += Math.min(5, sourceOverlap * 2);
        reasons.push('shared source');
      }
      const tokenOverlap = Array.from(knowledgeEntryTokenSet(item)).filter(token => targetTokens.has(token)).length;
      if (tokenOverlap) score += Math.min(3, tokenOverlap);
      return { entry: item, score, reasons: Array.from(new Set(reasons)) };
    })
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score || b.entry.updatedAt.localeCompare(a.entry.updatedAt));
}

function knowledgeMapClusters(entries: KnowledgeEntry[], workspaces: WorkspaceEntry[]): KnowledgeMapCluster[] {
  const map = new Map<string, KnowledgeMapCluster>();
  for (const entry of entries) {
    const topic = knowledgePrimaryTopic(entry, workspaces);
    const cluster = map.get(topic) || { topic, entries: [], sourceCount: 0, staleCount: 0 };
    cluster.entries.push(entry);
    cluster.sourceCount += knowledgeSourceItems(entry, workspaces).length;
    if (sourceFreshnessTone(aggregateSourceFreshness(entry)) === 'warn') cluster.staleCount += 1;
    map.set(topic, cluster);
  }
  return Array.from(map.values())
    .map(cluster => ({ ...cluster, entries: [...cluster.entries].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)) }))
    .sort((a, b) => b.entries.length - a.entries.length || a.topic.localeCompare(b.topic));
}

function sessionTitle(session: SessionInfo): string {
  return session.title || session.lastQuestion || session.lastMessageText || session.sessionId.slice(0, 12);
}

function shortScheduleTitle(title: string): string {
  const cleaned = title
    .replace(/https?:\/\/\S+/g, '')
    .replace(/[#*_`[\]()>]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const base = cleaned || title.trim() || 'chat';
  return base.length > 24 ? `${base.slice(0, 21).trim()}...` : base;
}

function chatScheduleDraftValue(draft: ChatScheduleProposalDraft): string {
  if (draft.schedule === 'manual') return 'manual';
  if (draft.schedule === 'daily') return `daily@${draft.time}`;
  if (draft.schedule === 'weekly') return `weekly@${draft.weekday}@${draft.time}`;
  if (draft.schedule === 'biweekly') return `biweekly@${draft.weekday}@${draft.time}`;
  if (draft.schedule === 'monthly') return `monthly@${draft.day}@${draft.time}`;
  return 'manual';
}

function cleanChatScheduleSeed(value: string): string {
  const raw = value.trim();
  return matchChatSlashQuery(raw) === null ? raw : '';
}

function buildChatSchedulePrompt(input: {
  instruction: string;
  projectName: string;
  targetLabel: string;
  permissionMode: ChatPermissionMode;
  effort: string;
  referenceLabel: string;
}): string {
  const instruction = input.instruction.trim() || 'Review the project, summarize what changed, and recommend the next useful action.';
  return [
    `Recurring chat task: ${instruction}`,
    '',
    `Project: ${input.projectName || 'current project'}`,
    `Target: ${input.targetLabel || 'default agent'}`,
    `Mode: ${input.permissionMode}`,
    `Effort: ${input.effort}`,
    input.referenceLabel ? `Project references: ${input.referenceLabel}` : '',
    '',
    'Use the project context, keep the run concise, call out blockers, and finish with the next recommended action.',
  ].filter(Boolean).join('\n');
}

function downloadTextArtifact(filename: string, content: string, type = 'text/markdown;charset=utf-8') {
  const safeName = (filename || 'session-export.md').replace(/[\\/]+/g, '-');
  const blob = new Blob([content], { type });
  downloadBlobArtifact(safeName, blob);
}

function downloadBlobArtifact(filename: string, blob: Blob) {
  const safeName = (filename || 'pikiclaw-artifact').replace(/[\\/]+/g, '-');
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = safeName;
  anchor.rel = 'noopener';
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

async function exportConversationMarkdown(item: RecentConversation) {
  const agent = item.session.agent || '';
  if (!agent) throw new Error('Missing session agent.');
  const res = await api.exportSession(item.workdir, agent, item.session.sessionId, 'markdown');
  if (!res.ok || !res.content) throw new Error(res.error || 'Export failed.');
  downloadTextArtifact(res.filename || `session-${agent}-${item.session.sessionId.slice(0, 8)}.md`, res.content);
  return res.filename;
}

function conversationDateSection(session: SessionInfo, copy: ReturnType<typeof copyFor>): string {
  const time = sessionTime(session);
  if (!time) return copy.older;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const day = 86_400_000;
  if (time >= today) return copy.today;
  if (time >= today - day) return copy.yesterday;
  if (time >= today - 7 * day) return copy.previous7Days;
  if (time >= today - 30 * day) return copy.previous30Days;
  return copy.older;
}

function conversationMatchesFilter(item: RecentConversation, filter: ConversationFilter): boolean {
  if (filter === 'all') return true;
  if (filter === 'running') return item.session.runState === 'running' || item.session.running === true;
  if (filter === 'pinned') return item.session.pinned === true;
  if (filter === 'incomplete') return item.session.runState === 'incomplete';
  if (filter === 'completed') return item.session.runState === 'completed';
  return true;
}

function conversationAttentionTone(session: SessionInfo): ConversationAttentionTone | null {
  if (session.userStatus === 'done' || session.userStatus === 'parked') return null;
  const displayState = sessionDisplayState(session);
  if (displayState === 'running') return 'running';
  if (displayState === 'incomplete' || session.userStatus === 'review' || session.classification?.outcome === 'blocked') return 'review';
  return isUnreadCompletedSession(session) ? 'unread' : null;
}

function conversationAttentionWeight(tone: ConversationAttentionTone): number {
  if (tone === 'running') return 0;
  if (tone === 'review') return 1;
  return 2;
}

function conversationAttentionLabel(tone: ConversationAttentionTone): string {
  if (tone === 'running') return 'Live';
  if (tone === 'review') return 'Review';
  return 'Unread';
}

function conversationAttentionPreview(session: SessionInfo): string {
  return [
    session.lastMessageText,
    session.lastAnswer,
    session.classification?.summary,
    session.runDetail,
    session.lastQuestion,
  ].map(value => String(value || '').replace(/\s+/g, ' ').trim()).find(Boolean) || '';
}

function buildModelOptions(agents: AgentRuntimeStatus[] | undefined, defaultAgent: string): ModelTargetOption[] {
  const out: ModelTargetOption[] = [];
  const seen = new Set<string>();
  for (const item of agents || []) {
    const agent = String(item.agent || '').trim();
    if (!agent || agent === 'openclaw' || item.installed === false) continue;
    const agentLabel = item.label || getAgentMeta(agent).shortLabel;
    const models = (item.byokModels?.length ? item.byokModels : item.models) || [];
    const selectedModel = item.selectedModel || item.nativeSelectedModel || '';
    const allModels = [...models];
    if (selectedModel && !allModels.some(model => model.id === selectedModel)) {
      allModels.unshift({ id: selectedModel, alias: null });
    }
    for (const model of allModels) {
      const id = String(model.id || '').trim();
      if (!id) continue;
      const key = `${agent}:${id}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({
        agent,
        model: id,
        label: model.alias || shortenModel(id),
        detail: item.byokProviderName ? `${agentLabel} · ${item.byokProviderName}` : agentLabel,
      });
    }
  }
  out.sort((a, b) => {
    if (a.agent === defaultAgent && b.agent !== defaultAgent) return -1;
    if (a.agent !== defaultAgent && b.agent === defaultAgent) return 1;
    return a.label.localeCompare(b.label);
  });
  return out.slice(0, 80);
}

function parseTarget(value: string): ChatLaunchTarget | null {
  if (value.startsWith('assistant:')) {
    const assistantId = value.slice('assistant:'.length).trim();
    return assistantId ? { kind: 'assistant', assistantId } : null;
  }
  if (value.startsWith('model:')) {
    const [, agent = '', encodedModel = ''] = value.split(':');
    const model = decodeURIComponent(encodedModel || '').trim();
    return agent && model ? { kind: 'model', agent, model } : null;
  }
  if (value.startsWith('agent:')) {
    const agent = value.slice('agent:'.length).trim();
    return agent ? { kind: 'agent', agent } : null;
  }
  return null;
}

