type PatternPreviewTone = 'workflow' | 'skill' | 'mcp' | 'cli' | 'assistant' | 'automation' | 'tool';

type PatternPreviewStat = {
  label: string;
  value: ReactNode;
};

function patternPreviewIcon(tone: PatternPreviewTone): string {
  if (tone === 'workflow' || tone === 'automation') return 'workflow';
  if (tone === 'assistant') return 'assistant';
  return 'tools';
}

function capabilityPatternTone(kind: CapabilityFilter): PatternPreviewTone {
  if (kind === 'skills') return 'skill';
  if (kind === 'mcp') return 'mcp';
  if (kind === 'cli') return 'cli';
  if (kind === 'assistants') return 'assistant';
  if (kind === 'automation') return 'automation';
  return 'tool';
}

