  const filteredSlashCommands = useMemo(() => {
    if (slashQuery === null) return [];
    const query = slashQuery.trim().toLowerCase();
    const filtered = query
      ? slashCommands.filter(command => [command.name, command.label, command.description, command.badge].join(' ').toLowerCase().includes(query))
      : slashCommands;
    return filtered.slice(0, 12);
  }, [slashCommands, slashQuery]);
  const slashMenuOpen = slashQuery !== null && slashDismissedValue !== prompt && filteredSlashCommands.length > 0 && !sending;
