                    <span className="truncate text-[13px] font-semibold text-fg">{item.title}</span>
                    {item.pinned && (
                      <span className="shrink-0 rounded-md border border-primary/25 bg-primary/[0.10] px-1.5 py-0.5 text-[10px] font-semibold text-primary">Always-on</span>
                    )}
